// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testRegression_property() public {
        NonPayableTarget target = new NonPayableTarget();

        vm.deal(address(this), 2 ether);

        vm.prank(address(this));
        (bool success,) = address(c).call{value: 2 ether}("");
        require(success, "initial deposit failed");


        bool ok;
        vm.prank(address(this));
        try c.sendMoney(address(target), 1 ether, "") {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok, "sendMoney should not revert");

        bool withdrawOk;
        vm.prank(address(this));
        try c.withdrawAll() {
            withdrawOk = true;
        } catch {
            withdrawOk = false;
        }

        assertTrue(!withdrawOk, "Reference: withdrawAll should revert; bug would not");
    }
}

contract NonPayableTarget {
    fallback() external payable {
        revert("non-payable");
    }
}
